import zipfile, re
import xml.etree.ElementTree as ET

RELNS = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

def local(tag):
    return tag.split('}')[-1]

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    n = 0
    for ch in m.group(1):
        n = n * 26 + (ord(ch) - 64)
    return n - 1, int(m.group(2)) - 1

def col_letter(idx):
    s = ''
    idx += 1
    while idx:
        idx, rem = divmod(idx - 1, 26)
        s = chr(65 + rem) + s
    return s

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Archive contents:", names)

    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheet_ids = []
    for el in wb.iter():
        if local(el.tag) == 'sheet':
            sheet_ids.append((el.get('name'), el.get(RELNS + 'id')))
    print("Sheets:", sheet_ids)

    relmap = {}
    if 'xl/_rels/workbook.xml.rels' in names:
        rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        for rel in rels.iter():
            if local(rel.tag) == 'Relationship':
                relmap[rel.get('Id')] = rel.get('Target')
    print("Rel map:", relmap)

    shared = []
    if 'xl/sharedStrings.xml' in names:
        sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in sst.iter():
            if local(si.tag) == 'si':
                shared.append(''.join(t.text or '' for t in si.iter() if local(t.tag) == 't'))
    print("Shared strings:", shared)

    grand_total = 0.0
    for sname, rid in sheet_ids:
        target = relmap.get(rid)
        path = 'xl/' + target if target and not target.startswith('/') else target
        ws = ET.fromstring(z.read(path))
        grid = {}
        for row in ws.iter():
            if local(row.tag) != 'row':
                continue
            r = int(row.get('r'))
            for c in row:
                if local(c.tag) != 'c':
                    continue
                col, _ = col_to_idx(c.get('r'))
                t = c.get('t')
                v = None
                for child in c:
                    if local(child.tag) == 'v':
                        v = child.text
                    elif local(child.tag) == 'is':
                        v = ''.join(x.text or '' for x in child.iter() if local(x.tag) == 't')
                if t == 's' and v is not None:
                    v = shared[int(v)]
                grid[(r, col)] = v

        maxr = max(r for r, c in grid) if grid else 0
        maxc = max(c for r, c in grid) if grid else 0
        print(f"\n=== Sheet: {sname} (rows={maxr}, cols={maxc+1}) ===")
        header = '     ' + ' | '.join(col_letter(c) for c in range(maxc + 1))
        print(header)
        for r in range(1, maxr + 1):
            cells = []
            for c in range(maxc + 1):
                val = grid.get((r, c), '')
                cells.append('' if val is None else str(val))
            print(f"r{r:3d} " + ' | '.join(cells))

        col_sums = {}
        for (r, c), val in grid.items():
            if r == 1:
                continue
            try:
                f = float(val)
            except (TypeError, ValueError):
                continue
            col_sums[c] = col_sums.get(c, 0.0) + f
            grand_total += f
        print("Numeric column sums (excluding header row):",
              {col_letter(c): round(s, 2) for c, s in sorted(col_sums.items())})

    print("\nGRAND TOTAL (all numeric cells, all sheets):", round(grand_total, 2))

